using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
// </SnippetAddUsings>

namespace TransformationCS
{
    // <SnippetBaseClass>
    public class TypeInferenceRewriter : CSharpSyntaxRewriter
    // </SnippetBaseClass>
    {
        // <SnippetConstruction>
        private readonly SemanticModel SemanticModel;

        public TypeInferenceRewriter(SemanticModel semanticModel) => SemanticModel = semanticModel;
        // </SnippetConstruction>

        // five
        public override SyntaxNode VisitLocalDeclarationStatement(LocalDeclarationStatementSyntax node)
        {
            // <SnippetExclusions>
            if (node.Declaration.Variables.Count > 1)
            {
                return node;
            }
            if (node.Declaration.Variables[0].Initializer == null)
            {
                return node;
            }
            // </SnippetExclusions>

            // <SnippetExtractTypeSymbol>
            var declarator = node.Declaration.Variables.First();
            var variableTypeName = node.Declaration.Type;

            var variableType = (ITypeSymbol)SemanticModel
                .GetSymbolInfo(variableTypeName)
                .Symbol;
            // </SnippetExtractTypeSymbol>

            // <SnippetBindInitializer>
            var initializerInfo = SemanticModel.GetTypeInfo(declarator.Initializer.Value);
            // </SnippetBindInitializer>

            // <SnippetReplaceNode>
            if (SymbolEqualityComparer.Default.Equals(variableType, initializerInfo.Type))
            {
                TypeSyntax varTypeName = SyntaxFactory.IdentifierName("var")
                    .WithLeadingTrivia(variableTypeName.GetLeadingTrivia())
                    .WithTrailingTrivia(variableTypeName.GetTrailingTrivia());

                return node.ReplaceNode(variableTypeName, varTypeName);
            }
            else
            {
                return node;
            }
            // </SnippetReplaceNode>
        }
    }
}

using System;
using Microsoft.Data.Sqlite;

namespace BatchingSample
{
    class Program
    {
        static void Main()
        {
            var connection = new SqliteConnection("Data Source=:memory:");
            connection.Open();

            // SQLite doesn't support batching natively. Since there's no network involved, it
            // wouldn't really help with performance anyway. Batching is implemented in
            // Microsoft.Data.Sqlite as a convenience. For better command performance, see
            // BulkInsertSample.

            var createCommand = connection.CreateCommand();
            createCommand.CommandText =
            @"
                CREATE TABLE blog (
                    id INTEGER PRIMARY KEY,
                    name TEXT
                );

                CREATE TABLE post (
                    id INTEGER PRIMARY KEY,
                    title TEXT,
                    blog_id INTEGER NOT NULL,
                    FOREIGN KEY (blog_id) REFERENCES blog
                );

                INSERT INTO blog
                VALUES (1, 'Brice''s Blog');

                INSERT INTO post
                VALUES (1, 'Hello, World!', 1),
                       (2, 'SQLite on .NET Core', 1);
            ";
            createCommand.ExecuteNonQuery();

            #region snippet_Batching
            // Batch two SELECT statements into a single command
            var command = connection.CreateCommand();
            command.CommandText =
            @"
                SELECT *
                FROM blog;

                SELECT *
                FROM post;
            ";
            using (var reader = command.ExecuteReader())
            {
                // Read the first result set
                while (reader.Read())
                {
                    Console.WriteLine($"Blog {reader["id"]}: {reader["name"]}");
                }

                // Read the second result set
                reader.NextResult();
                while (reader.Read())
                {
                    Console.WriteLine($"Post {reader["id"]}: {reader["title"]}");
                }
            }
            #endregion
        }
    }
}

