func ExampleWatcher_watch() {
	forUnitTestsRunInMockedContext(mockWatcherWatch, func() {
		cli, err := clientv3.New(clientv3.Config{
			Endpoints:   exampleEndpoints(),
			DialTimeout: dialTimeout,
